        on ? 'text-ink' : 'text-ink-3 hover:text-ink',
      )}
    >
      {label}
    </button>
  )
  return (
    <header className="relative z-20 flex h-[72px] shrink-0 items-center justify-center px-4 text-[length:var(--small)] text-ink-2 lg:px-8">
      <a
        href="/"
