import { Check, ChevronRight, ExternalLink, FileSearch, MailCheck, MoreHorizontal, Phone, Sparkles, Workflow } from 'lucide-react'
import { useEffect, useRef, useState, type ButtonHTMLAttributes, type ReactNode } from 'react'
import { EvidenceItem, Trail } from '@/components/EvidenceDrawer'
import { OpenAnchor, useAnchors, type Anchor } from '@/components/SourceAnchors'
import { Button } from '@/components/ui/button'
import { VoiceCall } from '@/components/VoiceCall'
import {
  DONE_WORD, costText, fmtNum, partName, post, sentence, tidy, until, type Card, type State,
} from '@/lib/api'
import {
  languageOf, mismatchPair, replyFacts, routineActionOf, routineOf, sameIssueOn, sourceName, splitValue, when, type Group,
} from '@/lib/decisions'
import { cn } from '@/lib/utils'
import { PaneHints } from './routines/PaneHints'
import { UndoAction } from './routines/Undo'

export interface Offer {
  /** Open cards left that look like the one just decided. */
  more: number
  onYes: () => void
  onNext: () => void
}

interface Props {
  card: Card
  state: State
  nowMs: number
  group?: Group | null
  /** Opened from the deep link (/d/<id>): whoever it is routed to can act on it here. */
  direct?: boolean
  /** Listen for a / Enter / Esc (the desktop pane). */
  keys?: boolean
  onChanged: () => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
  ringing?: boolean
  onRingingDone?: () => void
  offer?: Offer | null
}

const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))
const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))

export function DecisionPane({
  card, state, nowMs, group, direct, keys, onChanged, onDrawer, ringing, onRingingDone, offer,
}: Props) {
  const [sel, setSel] = useState(() => Math.max(0, card.options.findIndex((o) => o.recommended)))
  const [mode, setMode] = useState<'idle' | 'edit' | 'escalate'>('idle')
  const [text, setText] = useState('')
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const [confirm, setConfirm] = useState(false)
  const [more, setMore] = useState(false)
  const moreRef = useRef<HTMLDivElement>(null)
  const anchors = useAnchors(card.id)
  // While the recommendation is out of view, the action bar says what Approve does.
  const recRef = useRef<HTMLElement>(null)
  const [recSeen, setRecSeen] = useState(true)
  useEffect(() => {
    const el = recRef.current
    if (!el) return
    const io = new IntersectionObserver(([e]) => setRecSeen(e.isIntersecting), { threshold: 0.4 })
    io.observe(el)
    return () => io.disconnect()
  }, [sel])

  const opt = card.options[sel]
  const due = until(card.deadline, nowMs)
  const other = card.routed_to_other || card.status === 'escalated'
  const closed = card.status !== 'open' && card.status !== 'escalated'
  const actionable = (!other || !!direct) && !closed && !!opt
  const who = first(card.approver) || 'the approver'
  const part = card.part_name || partName(card.part, state.cards)
  const pair = mismatchPair(card)
  const rest = card.evidence.map((_, i) => i).filter((i) => !pair || (i !== pair.sys && i !== pair.doc))
  const recommended = opt?.recommended || (sel === 0 && !card.options.some((o) => o.recommended))
  const routine = closed ? routineOf(state, card.id) : null
  const undoId = routine ? routineActionOf(state, card.id) : null
  const facts = replyFacts(card)
  const same = group ? sameIssueOn(group) : null

  useEffect(() => {
    if (!more) return
    const off = (e: MouseEvent) => { if (!moreRef.current?.contains(e.target as Node)) setMore(false) }
    document.addEventListener('mousedown', off)
    return () => document.removeEventListener('mousedown', off)
  }, [more])

  async function act(fn: () => Promise<unknown>) {
    setBusy(true)
    try { await fn() } finally { setBusy(false); setConfirm(false) }
  }
  const approve = () =>
    act(async () => {
      await post(`/api/cards/${card.id}/approve`, { option: sel, text: mode === 'edit' ? text : undefined })
      setMode('idle')
      onChanged()
    })
  const escalate = () =>
    act(async () => { await post(`/api/cards/${card.id}/escalate`, { note }); setMode('idle'); onChanged() })
  const dismiss = () => act(async () => { setMore(false); await post(`/api/cards/${card.id}/dismiss`); onChanged() })

  // Keyboard: a asks, Enter approves, Esc cancels. Never while typing.
  const approveRef = useRef(approve)
  approveRef.current = approve
  useEffect(() => {
    if (!keys) return
    const onKey = (e: KeyboardEvent) => {
      if (typing(e.target) || e.metaKey || e.ctrlKey || e.altKey) return
      if (confirm && e.key === 'Enter') { e.preventDefault(); void approveRef.current() }
      else if (confirm && e.key === 'Escape') { e.preventDefault(); setConfirm(false) }
      else if (!confirm && e.key.toLowerCase() === 'a' && actionable && mode === 'idle' && !busy) { e.preventDefault(); setConfirm(true) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [keys, confirm, actionable, mode, busy])

  return (
    <article className="pane-in space-y-6" aria-label={tidy(card.headline)}>
      {/* identity and time */}
      <div className="space-y-2">
        <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 text-sm">
          <span className="font-semibold text-ink-2">{[card.supplier_name, part].filter(Boolean).join(' · ') || 'Soony'}</span>
          {card.deadline && !closed && (
            <span className={cn('font-semibold tabular-nums', card.level === 'red' && due?.urgent ? 'text-stop' : 'text-ink')}>
              Decide by {when(card.deadline, nowMs)}{due ? <span className="font-normal text-ink-3"> · {due.text}</span> : null}
            </span>
          )}
        </div>
        <h1 className="text-[24px] font-bold leading-tight tracking-tight sm:text-[28px]">{tidy(card.headline)}</h1>
        {same && <p className="text-sm font-semibold text-ink-2">Same issue on {same}.</p>}
      </div>

      {/* outcome so far */}
      {closed && (
        <div className="flex flex-wrap items-center gap-x-2 gap-y-1 rounded-xl bg-panel px-4 py-3 text-[15px] ring-1 ring-line">
          <Check size={18} className={routine ? 'text-routine' : 'text-ok'} />
          <span className="font-semibold">{DONE_WORD[card.status] ?? 'Done'}</span>
          {card.ui?.at && <span className="text-ink-2">{when(card.ui.at, nowMs)}</span>}
          {routine && (
            <span className="inline-flex items-center gap-1 text-sm font-semibold text-routine">
              <Workflow size={14} /> By routine · {routine}
            </span>
          )}
          {undoId && <UndoAction actionId={undoId} onUndone={onChanged} className="ml-auto" />}
        </div>
      )}
      {closed && offer && <AutomateOffer card={card} offer={offer} />}

      {other && (
        <div className="flex items-start gap-3 rounded-xl bg-panel px-4 py-3 text-[15px] text-ink-2 ring-1 ring-line">
          <Phone size={18} className="mt-0.5 shrink-0 text-ink-3" />
          <div>
            <div className="font-semibold text-ink">{card.status === 'escalated' ? `Waiting for ${who}` : `With ${who}`}</div>
            {card.reason && <div className="mt-0.5">{sentence(card.reason)}</div>}
          </div>
        </div>
      )}

      <PaneHints card={card} onChanged={onChanged} />

      {facts && (
        <div className={cn('flex items-start gap-2.5 rounded-xl px-4 py-3 text-[15px] ring-1', facts.late ? 'bg-stop/[0.05] ring-stop/25' : 'bg-good/5 ring-good/25')}>
          <MailCheck size={18} className={cn('mt-0.5 shrink-0', facts.late ? 'text-stop' : 'text-good')} />
          <span className="font-semibold text-ink">
            {facts.text}
            {facts.late && <span className="text-stop"> · after launch</span>}
          </span>
        </div>
      )}

      {/* the contradiction, with its source */}
      {pair ? (
        <Hero card={card} pair={pair} anchors={anchors.items} ready={anchors.ready} />
      ) : (
        card.number != null && card.number > 0 && (
          <div className="rounded-xl bg-panel p-5 ring-1 ring-line">
            <div className={cn('text-[44px] font-extrabold leading-none tabular-nums sm:text-[52px]', card.level === 'red' ? 'text-stop' : card.level === 'amber' ? 'text-warn' : 'text-ink')}>
              {fmtNum(card.number)}
            </div>
            <div className="mt-2 text-[16px] text-ink-2">{card.number_label}</div>
          </div>
        )
      )}
      {card.summary && <p className="text-[16px] leading-relaxed text-ink-2">{sentence(card.summary)}</p>}

      {(rest.length > 0 || card.trail.length > 0) && (
        <div className="divide-y divide-line border-y border-line">
          {rest.length > 0 && (
            <Fold title={`More evidence · ${rest.length}`}>
              <div className="space-y-3">
                {rest.map((i) => <EvidenceItem key={i} e={card.evidence[i]} anchors={anchors.items?.[i]} ready={anchors.ready} />)}
              </div>
            </Fold>
          )}
          {card.trail.length > 0 && (
            <Fold title="How we know">
              <Trail card={card} />
            </Fold>
          )}
        </div>
      )}

      {/* what to do */}
      {actionable && (
        <>
          <section ref={recRef} className="rounded-xl bg-panel p-5 ring-1 ring-line">
            <div className="text-xs font-bold uppercase tracking-wide text-ink-3">{recommended ? 'We recommend' : 'Your choice'}</div>
            <div className="mt-1.5 text-[20px] font-bold leading-snug">{sentence(opt.action)}</div>
            {opt.effect && <p className="mt-1 text-[16px] text-ink-2">{sentence(opt.effect)}</p>}
            <div className="mt-3 inline-flex rounded-md bg-white px-2.5 py-1 text-sm font-semibold ring-1 ring-line">{costText(opt.cost)}</div>
          </section>

          {card.options.length > 1 && (
            <ul className="-mt-3 space-y-0.5">
              {card.options.map((o, i) =>
                i === sel ? null : (
                  <li key={i}>
                    <button
                      onClick={() => { setSel(i); setMode('idle'); setConfirm(false) }}
                      className="flex w-full cursor-pointer items-start gap-2 rounded-lg px-3 py-2.5 text-left text-[15px] text-ink-2 hover:bg-panel"
                    >
                      <ChevronRight size={16} className="mt-0.5 shrink-0 text-ink-3" />
                      <span className="min-w-0 font-medium"><span className="text-ink-3">Or: </span>{sentence(o.action)}</span>
                      <span className="ml-auto shrink-0 pl-2 text-sm text-ink-3">{costText(o.cost)}</span>
                    </button>
                  </li>
                ),
              )}
            </ul>
          )}

          {mode === 'edit' && (
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              rows={7}
              className="w-full rounded-xl border border-line p-4 text-[15px] leading-relaxed focus:outline-2 focus:outline-ok"
              aria-label="Edit draft"
            />
          )}
          {mode === 'escalate' && (
            <div className="rounded-xl border border-line p-4">
              <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">Brief for {who}</div>
              <p className="mt-1 text-[15px] text-ink-2">{tidy(card.escalation_brief)}</p>
              <input
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="Add one line (optional)"
                className="mt-3 h-10 w-full rounded-lg border border-line px-3 text-[15px] focus:outline-2 focus:outline-ok"
              />
              <div className="mt-3 flex gap-2">
                <Button size="sm" disabled={busy} onClick={escalate}>Send to {who}</Button>
                <Button size="sm" variant="ghost" onClick={() => setMode('idle')}>Cancel</Button>
              </div>
            </div>
          )}

          {/* The action bar stays in view while the evidence scrolls. */}
          <div className="sticky bottom-3 z-10 space-y-2 rounded-xl border border-line bg-white/95 p-3 shadow-[0_8px_24px_rgba(15,23,42,0.08)] backdrop-blur">
            {confirm && (
              <div className="flex flex-wrap items-center gap-x-3 gap-y-1 rounded-lg bg-ok/5 px-3 py-2.5 text-[15px] ring-1 ring-ok/30" role="alert">
                <span className="min-w-0 flex-1">
                  Press <kbd>Enter</kbd> to approve: <span className="font-semibold">{sentence(opt.action)}</span>{' '}
                  <span className="text-ink-2">({costText(opt.cost)})</span>
                </span>
                <span className="text-sm text-ink-3"><kbd>Esc</kbd> cancels</span>
              </div>
            )}
            {!confirm && !recSeen && (
              <p className="line-clamp-2 px-1 text-sm text-ink-2">
                <span className="text-ink-3">{recommended ? 'We recommend: ' : 'Your choice: '}</span>
                <span className="font-semibold text-ink">{sentence(opt.action)}</span> · {costText(opt.cost)}
              </p>
            )}
            <div className="flex flex-wrap items-center gap-2 max-md:flex-nowrap max-md:has-[ul]:flex-wrap">
              <Button disabled={busy} onClick={approve} className="px-6 max-md:flex-1 max-md:px-3">
                <Check size={18} /> {mode === 'edit' ? 'Approve edited' : 'Approve'}
                {keys && <kbd className="ml-1 border-white/40 bg-white/15 text-white">A</kbd>}
              </Button>
              <Voice card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} />
              <Button
                variant="outline"
                className="max-md:hidden"
                disabled={!opt.draft && mode !== 'edit'}
                title={opt.draft ? undefined : 'This option has no draft to edit'}
                onClick={() => { setText(opt.draft ?? ''); setMode(mode === 'edit' ? 'idle' : 'edit') }}
              >
                Edit
              </Button>
              <Button variant="outline" className="max-md:hidden" onClick={() => setMode(mode === 'escalate' ? 'idle' : 'escalate')}>
                Escalate
              </Button>
              <div ref={moreRef} className="relative ml-auto">
                <Button variant="ghost" className="w-11 px-0" aria-label="More actions" onClick={() => setMore(!more)}>
                  <MoreHorizontal size={18} />
                </Button>
                {more && (
                  <div className="absolute bottom-12 right-0 z-20 w-60 rounded-xl border border-line bg-white p-1 shadow-lg">
                    {opt.draft && (
                      <MenuItem className="md:hidden" onClick={() => { setMore(false); setText(opt.draft ?? ''); setMode('edit') }}>Edit the draft</MenuItem>
                    )}
                    <MenuItem className="md:hidden" onClick={() => { setMore(false); setMode('escalate') }}>Escalate to {who}</MenuItem>
                    <MenuItem disabled={busy} onClick={dismiss} hint="Nothing to do; take it off the list">Dismiss</MenuItem>
                  </div>
                )}
              </div>
            </div>
          </div>
        </>
      )}

      {card.ui?.reply && (
        <section className="rounded-r-xl border-l-4 border-good bg-good/5 px-4 py-3">
          <div className="text-xs font-bold uppercase tracking-wide text-good">
            Reply from {card.ui.reply_from || 'supplier'}{card.ui.reply_at ? ` · ${when(card.ui.reply_at, nowMs)}` : ''}
          </div>
          <p className="mt-1 text-[16px] font-medium leading-snug">{card.ui.reply}</p>
          {card.ui.reply_text && (
            <details className="mt-2">
              <summary className="cursor-pointer text-sm text-ink-3">Original email</summary>
              <pre className="mt-1 whitespace-pre-wrap break-words font-sans text-sm text-ink-2">{card.ui.reply_text}</pre>
            </details>
          )}
        </section>
      )}

      {!actionable && !closed && <Voice card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} />}

      <button
        onClick={() => onDrawer(card, 'evidence')}
        className="inline-flex cursor-pointer items-center gap-1.5 text-sm font-semibold text-ink-2 hover:text-ink md:hidden"
      >
        <FileSearch size={16} /> Show all evidence
      </button>
    </article>
  )
}

// VoiceCall brings its own "Talk it through" button and transcript; it sits in the action row,
// and takes the full width while ringing or once a transcript shows.
function Voice(p: { card: Card; onChanged: () => void; ringing?: boolean; onRingingDone?: () => void }) {
  return (
    <div
      className={cn(
        'min-w-0 [&>div]:mt-0 [&_ul]:max-h-56 [&_ul]:overflow-y-auto has-[ul]:basis-full',
        '[&_button]:h-11 [&_button]:text-[15px] max-md:[&_button]:px-3 md:[&_button]:px-5',
        p.ringing && 'order-first basis-full',
      )}
    >
      <VoiceCall card={p.card} onChanged={p.onChanged} ringing={p.ringing} onRingingDone={p.onRingingDone} />
    </div>
  )
}

function MenuItem({ children, hint, className, ...rest }: { children: ReactNode; hint?: string } & ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button {...rest} className={cn('w-full cursor-pointer rounded-lg px-3 py-2 text-left text-[15px] font-semibold text-ink-2 hover:bg-panel', className)}>
      {children}
      {hint && <span className="block text-xs font-normal text-ink-3">{hint}</span>}
    </button>
  )
}

function Fold({ title, children }: { title: string; children: ReactNode }) {
  return (
    <details className="group">
      <summary className="flex cursor-pointer list-none items-center gap-1.5 py-3 text-sm font-semibold text-ink-2 hover:text-ink [&::-webkit-details-marker]:hidden">
        <ChevronRight size={16} className="transition-transform group-open:rotate-90" /> {title}
      </summary>
      <div className="pb-4">{children}</div>
    </details>
  )
}

/** After a decision by hand: offer to handle the next ones like it, in place. */
function AutomateOffer({ card, offer }: { card: Card; offer: Offer }) {
  const who = card.supplier_name
  return (
    <section className="slide-in rounded-xl border border-routine/30 bg-routine/5 p-5" aria-live="polite">
      <div className="text-[18px] font-bold leading-snug">
        Done.{' '}
        {offer.more > 0
          ? `${offer.more} more like this${who ? ` from ${who}` : ''}. Handle them the same way?`
          : 'Handle the next one like this on its own?'}
      </div>
      <p className="mt-1 text-[15px] text-ink-2">Money and plan changes still come to you.</p>
      <div className="mt-4 flex flex-wrap gap-2">
        <Button onClick={offer.onYes} className="bg-routine hover:bg-[#6d28d9]"><Sparkles size={16} /> Show me the routine</Button>
        <Button variant="outline" onClick={offer.onNext}>Next decision</Button>
      </div>
    </section>
  )
}

// ---------------------------------------------------------------- hero

const where = (a: Anchor) =>
  a.kind === 'table' || a.kind === 'text' ? `row ${(a.row ?? 0) + 1}` : `p. ${a.page ?? 1}`
const docName = (doc: string) => (doc.split('/').pop() ?? doc).replace(/\.[a-z0-9]+$/i, '').replace(/_/g, ' ')

function Hero({
  card, pair, anchors, ready,
}: { card: Card; pair: { sys: number; doc: number }; anchors: Record<number, Anchor[]> | null; ready: boolean }) {
  const s = card.evidence[pair.sys]
  const d = card.evidence[pair.doc]
  const sysA = anchors?.[pair.sys] ?? []
  const docA = anchors?.[pair.doc] ?? []
  // The paper side opens right away; the system's row is one click away.
  const [pick, setPick] = useState<{ side: 'doc' | 'sys'; i: number } | null>(null)
  const active = pick ? (pick.side === 'doc' ? docA : sysA)[pick.i] : docA[0] ?? null
  const activeKey = pick ?? (docA[0] ? { side: 'doc' as const, i: 0 } : null)
  const tone = card.level === 'red' ? 'stop' : card.level === 'amber' ? 'warn' : null
  const lang = languageOf(d.source, d.language)
  const page = d.page ?? docA[0]?.page
  const docHead = `The document says${lang || page ? ` (${[lang, page ? `p. ${page}` : ''].filter(Boolean).join(', ')})` : ''}`
  const sources = [
    ...docA.map((a, i) => ({ side: 'doc' as const, i, a })),
    ...sysA.map((a, i) => ({ side: 'sys' as const, i, a })),
  ]

  return (
    <section className="space-y-3">
      <div className="grid items-stretch gap-3 md:grid-cols-[1fr_auto_1fr]">
        <Slab head="The system says" source={sourceName(s.source) || 'System'} value={s.value} />
        <div className="grid place-items-center text-[28px] font-bold text-ink-3 max-md:-my-2" aria-label="does not match">≠</div>
        <Slab head={docHead} source={sourceName(d.source) || 'Document'} value={d.value} tone={tone} />
      </div>

      {(d.quote || d.translation) && (
        <div className="space-y-1 px-1">
          {d.quote && <blockquote className="border-l-2 border-line pl-3 text-[15px] leading-relaxed text-ink">“{d.quote}”</blockquote>}
          {d.translation && <p className="pl-3.5 text-sm text-ink-2">In English: {d.translation}</p>}
        </div>
      )}

      {sources.length > 1 && (
        <div className="flex flex-wrap gap-1.5">
          {sources.map((x) => {
            const on = activeKey?.side === x.side && activeKey.i === x.i
            return (
              <button
                key={`${x.side}-${x.i}`}
                onClick={() => setPick({ side: x.side, i: x.i })}
                title={x.a.doc}
                className={cn(
                  'inline-flex max-w-full cursor-pointer items-center gap-1.5 rounded-full border px-3 py-1 text-sm',
                  on ? 'border-ink bg-ink font-semibold text-white' : 'border-line text-ink-2 hover:bg-panel',
                )}
              >
                <span className="shrink-0 font-semibold">{x.side === 'doc' ? 'Document' : 'System'}</span>
                <span className="truncate">{docName(x.a.doc)}</span>
                <span className={cn('shrink-0', on ? 'text-white/70' : 'text-ink-3')}>· {where(x.a)}</span>
              </button>
            )
          })}
        </div>
      )}
      {active ? (
        <OpenAnchor anchor={active} />
      ) : !ready ? (
        <p className="px-1 text-sm text-ink-3">Looking for this in the documents…</p>
      ) : d.doc ? (
        <a
          href={`/api/file?path=${encodeURIComponent(d.doc)}${d.page ? `#page=${d.page}` : ''}`}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1.5 px-1 text-sm font-semibold text-ok hover:underline"
        >
          Open the document <ExternalLink size={14} />
        </a>
      ) : null}
    </section>
  )
}

function Slab({ head, source, value, tone }: { head: string; source: string; value: Card['evidence'][number]['value']; tone?: 'stop' | 'warn' | null }) {
  const { big, rest } = splitValue(value)
  const long = big.length > 14
  return (
    <div
      className={cn(
        'min-w-0 rounded-xl p-5 ring-1',
        tone === 'stop' ? 'bg-stop/[0.05] ring-stop/25' : tone === 'warn' ? 'bg-warn/[0.06] ring-warn/25' : 'bg-white ring-line',
      )}
    >
      <div className={cn('text-xs font-bold uppercase tracking-wide', tone === 'stop' ? 'text-stop' : tone === 'warn' ? 'text-warn' : 'text-ink-3')}>
        {head}
      </div>
      <div className="mt-0.5 text-sm text-ink-2">{source}</div>
      <div
        className={cn(
          'mt-3 font-extrabold leading-none tabular-nums tracking-tight',
          long ? 'text-[28px] leading-tight' : 'text-[40px] sm:text-[48px]',
          tone === 'stop' ? 'text-stop' : tone === 'warn' ? 'text-warn' : 'text-ink',
        )}
      >
        {big}
      </div>
      {rest && <div className="mt-2 text-[16px] font-medium leading-snug text-ink-2">{rest}</div>}
    </div>
  )
}

import * as Dialog from '@radix-ui/react-dialog'
import { Check, Database, FileText } from 'lucide-react'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { AnchorCrop, NUM_OR_ID, fileUrl, normTok, useAnchors, type Anchor } from '@/components/SourceAnchors'
import { VoiceCall } from '@/components/VoiceCall'
import { undoAction, useLive } from '@/components/routines/live'
import { post, tidy, type Card, type Evidence, type State } from '@/lib/api'
import { languageOf, splitValue, when } from '@/lib/decisions'
import {
  actionText, claimOf, costLine, costsMoney, docKind, forToday, headlineOf, launchStatus, plural,
  recommendedIndex, routineCount, shortName, shortTitle, summaryLine, type Claim,
} from '@/lib/today'
import { cn } from '@/lib/utils'

// The Sunday flow: one decision at a time, the source one tap away, then "Done" and what's next.

export interface DoneInfo {
  card: Card
  text: string
  sub: string
  actionId: string | null
  /** Open look-alikes to offer a routine for; 0 when none (or a routine exists). */
  offer: number
  k: number
}

interface Props {
  state: State
  nowMs: number
  phone: boolean
  card: Card | null
  order: Card[]
  onFocus: (id: string) => void
  done: DoneInfo | null
  onDone: (d: { card: Card; text: string; sub: string; actionId: string | null }) => void
  onClearDone: () => void
  onChanged: () => void
  onRoutines: (request?: { cardId: string; k: number }) => void
  go: (path: string) => void
  ringing?: boolean
  onRingingDone?: () => void
  /** Routine proposals waiting for an OK plus drafts from calls. */
  pending: number
}

const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))

export function Today(p: Props) {
  const { state, nowMs, phone, card, done } = p
  const handled = routineCount(state, nowMs)
  const view = done ? 'done' : card ? 'decide' : 'clear'

  const foot = (
    <FootLines state={state} handled={handled} pending={p.pending} onRoutines={() => p.onRoutines()} go={p.go} nowMs={nowMs} center={!phone} />
  )

  const body =
    view === 'done' ? (
      <DoneView key={`done-${done!.k}`} {...p} done={done!} />
    ) : view === 'decide' ? (
      <Focus key={card!.id} {...p} card={card!} />
    ) : (
      <AllClear state={state} nowMs={nowMs} handled={handled} pending={p.pending} onRoutines={p.onRoutines} go={p.go} />
    )

  if (phone) {
    return (
      <main className="mx-auto w-full max-w-[560px] px-7 pb-[220px] pt-5">
        {body}
        {view === 'decide' && (handled > 0 || p.pending > 0) && <div className="mt-14">{foot}</div>}
      </main>
    )
  }
  // Desktop: a very quiet list on the left, the decision in a 640 px column.
  return (
    <div className="relative flex-1">
      <div className="mx-auto grid w-full max-w-[1440px] grid-cols-[240px_minmax(0,640px)] gap-x-16 px-12 pb-32 pt-24 xl:grid-cols-[300px_640px] xl:gap-x-[124px] xl:px-24">
        <aside aria-label="Needs you">
          {p.order.length > 0 && <QuietList {...p} />}
        </aside>
        <main className="min-w-0">{body}</main>
      </div>
      {view !== 'clear' && <div className="fixed inset-x-0 bottom-8 z-10 flex justify-center">{foot}</div>}
    </div>
  )
}

// ---------------------------------------------------------------- left list

function QuietList({ order, card, onFocus, state, nowMs }: Props) {
  // One line per problem: look-alikes fold into their first card.
  const seen = new Map<string, { c: Card; n: number }>()
  for (const c of order) {
    const k = `${c.supplier_id ?? c.supplier_name}|${c.kind}|${shortTitle(c, state).replace(/\d[\d,.]*/g, '#')}`
    const e = seen.get(k)
    if (e) e.n += 1
    else seen.set(k, { c, n: 1 })
  }
  const rows = [...seen.values()]
  const shown = rows.slice(0, 5)
  const more = rows.slice(5).reduce((n, r) => n + r.n, 0)
  return (
    <div>
      <p className="t-small mb-3 text-ink-3">Needs you</p>
      <ul className="-mx-3.5">
        {shown.map(({ c, n }) => {
          const on = card?.id === c.id
          return (
            <li key={c.id}>
              <button
                onClick={() => onFocus(c.id)}
                aria-current={on ? 'true' : undefined}
                className={cn(
                  't-small grid w-full cursor-pointer grid-cols-[8px_1fr_auto] items-baseline gap-3.5 rounded-[10px] px-3.5 py-3 text-left focus-visible:outline-2 focus-visible:outline-accent',
                  on ? 'bg-soft font-medium text-ink' : 'text-ink-2 hover:text-ink',
                )}
              >
                <i className={cn('h-[7px] w-[7px] -translate-y-px rounded-full', on ? 'bg-accent' : 'bg-ink-3')} />
                <span className="truncate">{shortTitle(c, state)}{n > 1 && <span className="font-normal text-ink-3"> · {n}</span>}</span>
                <span className="font-normal text-ink-3">{c.deadline ? when(c.deadline, nowMs) : ''}</span>
              </button>
            </li>
          )
        })}
      </ul>
      {more > 0 && <p className="t-small mt-2 text-ink-3">+{more} more</p>}
      <p className="t-small mt-6 text-ink-3"><kbd>J</kbd> <kbd>K</kbd> to move, <kbd>A</kbd> to approve</p>
    </div>
  )
}

// ---------------------------------------------------------------- one decision

function Focus(p: Props & { card: Card }) {
  const { card, state, nowMs, phone } = p
  const [sel, setSel] = useState(() => recommendedIndex(card))
  const [confirm, setConfirm] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [others, setOthers] = useState(false)
  const [passOn, setPassOn] = useState(false)
  const [note, setNote] = useState('')
  const [source, setSource] = useState<number | null>(null)
  // An email to a supplier is shown before it goes out: it cannot be taken back.
  const [review, setReview] = useState(false)
  const [draft, setDraft] = useState('')
  const [linesEl, setLinesEl] = useState<HTMLDivElement | null>(null)
  const anchors = useAnchors(card.id)
  const claim = claimOf(card)
  const today = forToday(card, state, nowMs)
  const opt = card.options[sel]
  const recommended = sel === recommendedIndex(card)
  const money = opt ? costsMoney(card, sel) : false
  const emails = !!opt && opt.channel === 'email' && /@/.test(opt.to ?? '')
  const late = card.level === 'red'

  async function act(fn: () => Promise<{ text: string; sub: string; actionId: string | null }>) {
    setBusy(true); setError('')
    try {
      const out = await fn()
      p.onDone({ card, ...out })
      p.onChanged()
    } catch (e) {
      setError(`That did not go through: ${(e as Error).message}. Nothing was sent.`)
    } finally { setBusy(false); setConfirm(false) }
  }
  const approve = (text?: string) =>
    act(async () => {
      const edited = text != null && text.trim() !== (opt?.draft ?? '').trim()
      const r = await post<{ action?: { id?: string; status?: string } }>(
        `/api/cards/${encodeURIComponent(card.id)}/approve`,
        edited ? { option: sel, text } : { option: sel },
      )
      const status = r.action?.status
      const at = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
      const sent = status === 'sent'
      const sub = sent
        ? `Sent to ${shortName(card.supplier_name) || opt?.to} at ${at}. You'll see the reply here.`
        : opt?.channel === 'notify' && opt.to ? `${opt.to} has it now.` : 'Recorded.'
      // A sent email cannot be undone, so no Undo is offered for it.
      return { text: doneFrom(card, sel, status), sub, actionId: sent ? null : r.action?.id ?? null }
    })
  const openReview = () => { setDraft(opt?.draft ?? ''); setReview(true) }
  const escalate = () =>
    act(async () => {
      const r = await post<{ id?: string }>(`/api/cards/${encodeURIComponent(card.id)}/escalate`, { note })
      return { text: `Passed on to ${card.approver || 'the approver'}.`, sub: 'You will see their answer here.', actionId: r?.id ?? null }
    })
  const dismiss = () =>
    act(async () => {
      const r = await post<{ id?: string }>(`/api/cards/${encodeURIComponent(card.id)}/dismiss`)
      return { text: 'Taken off the list.', sub: 'Nothing was sent.', actionId: r?.id ?? null }
    })
  const onApprove = () => (emails ? openReview() : money ? setConfirm(true) : void approve())

  // Keyboard (desktop): j/k walk, a asks, Enter approves, Esc cancels.
  const ref = useRef({ approve, confirm, busy, emails, openReview })
  ref.current = { approve, confirm, busy, emails, openReview }
  useEffect(() => {
    if (phone) return
    const onKey = (e: KeyboardEvent) => {
      if (typing(e.target) || e.metaKey || e.ctrlKey || e.altKey || source != null || review) return
      const k = e.key
      if (ref.current.confirm && k === 'Enter') { e.preventDefault(); void ref.current.approve() }
      else if (k === 'Escape') { setConfirm(false); setOthers(false) }
      else if ((k === 'a' || k === 'A') && opt && !ref.current.busy) {
        e.preventDefault()
        if (ref.current.emails) ref.current.openReview()
        else setConfirm(true)
      }
      else if (k === 'j' || k === 'k' || k === 'ArrowDown' || k === 'ArrowUp') {
        const i = p.order.findIndex((c) => c.id === card.id)
        const n = p.order[Math.min(p.order.length - 1, Math.max(0, i + (k === 'j' || k === 'ArrowDown' ? 1 : -1)))]
        if (n && n.id !== card.id) { e.preventDefault(); p.onFocus(n.id) }
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [phone, source, review, opt, card.id, p])

  const decideBy = card.deadline ? (new Date(card.deadline).getTime() <= nowMs ? 'decide now' : `decide by ${when(card.deadline, nowMs)}`) : ''
  const meta = [card.supplier_name || card.part_name, decideBy].filter(Boolean).join(' · ')

  const actions = opt && (
    <div className={cn(phone ? 'fixed inset-x-0 bottom-0 z-20 bg-gradient-to-t from-ground from-70% to-ground/0 px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-8' : 'mt-8')}>
      <div className={cn(phone && 'mx-auto max-w-[520px]')}>
        {confirm && (
          <p className={cn('t-small mb-3 text-ink-2', phone && 'text-center')} role="alert">
            Approve: <span className="text-ink">{actionText(card, sel).replace(/\.$/, '')}</span> ({costLine(card, sel).replace(/\.$/, '')})
            {!phone && <span className="text-ink-3"> · <kbd>Enter</kbd> confirms</span>}
          </p>
        )}
        {error && <p className="t-small mb-3 text-late" role="alert">{error}</p>}
        <div className={cn(phone ? 'grid justify-items-center gap-3.5' : 'flex flex-wrap items-center gap-6', p.ringing && phone && 'gap-5')}>
          <button
            onClick={confirm ? () => approve() : onApprove}
            disabled={busy}
            className={cn(
              'inline-flex cursor-pointer items-center justify-center rounded-xl font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60 t-body',
              // While the alert rings, Answer is the one blue button.
              p.ringing ? 'bg-soft text-ink hover:bg-hair' : 'bg-accent text-white shadow-[0_1px_2px_rgba(35,72,208,.25)] hover:bg-[#1d3db5]',
              phone ? 'h-[54px] w-full rounded-[14px]' : 'h-12 px-7',
            )}
          >
            {busy ? 'Sending…' : confirm ? 'Yes, approve' : emails ? 'Review email' : 'Approve'}
          </button>
          <div className={cn('flex items-center', phone ? 't-small gap-7' : 't-body gap-6', p.ringing && 'order-first w-full flex-col gap-4 pb-2 lg:items-start')}>
            <VoiceCall card={card} onChanged={p.onChanged} ringing={p.ringing} onRingingDone={p.onRingingDone} quiet linesEl={linesEl} />
            {confirm ? (
              <button onClick={() => setConfirm(false)} className="cursor-pointer text-ink-2 hover:text-ink">Cancel</button>
            ) : (
              <button onClick={() => setOthers(!others)} aria-expanded={others} className="cursor-pointer text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-accent">
                {others ? 'Fewer options' : 'Other options'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  )

  return (
    <article className="rise" aria-label={headlineOf(card, state)}>
      <p className="t-small mb-4 text-ink-3">{meta}</p>
      <h1 className="t-big text-ink">{headlineOf(card, state)}</h1>

      <p className="t-body mt-6 text-ink-2">
        {claim ? (
          <ClaimLine claim={claim} late={late} open={source} onOpen={setSource} />
        ) : (
          <Cited text={summaryLine(card)} anchors={anchors.items} onOpen={setSource} open={source} />
        )}
      </p>
      {today && (
        <p className="t-body mt-4 text-ink-2">For today: <span className="font-medium text-ink">{today.bold}</span>{today.rest}</p>
      )}

      {opt && (
        <div className={cn(phone ? 'mt-9' : 'mt-12')}>
          <p className="t-small mb-1.5 text-ink-3">{recommended ? 'We recommend' : 'Your choice'}</p>
          <p className="t-body text-ink">{actionText(card, sel)}{phone && <span className="text-ink-2"> {costLine(card, sel)}</span>}</p>
          {!phone && (
            <p className="t-body text-ink-2">{costLine(card, sel)}{opt.effect ? ` ${cap(tidy(opt.effect))}.`.replace(/\.\.$/, '.') : ''}</p>
          )}
        </div>
      )}

      {others && (
        <div className="fade mt-8 space-y-1" aria-label="Other options">
          {card.options.map((_, i) =>
            i === sel ? null : (
              <button
                key={i}
                onClick={() => { setSel(i); setOthers(false); setConfirm(false) }}
                className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
              >
                <span className="text-ink-3">Or </span>{actionText(card, i).replace(/^./, (c) => c.toLowerCase())}{' '}
                <span className="t-small text-ink-3">{costLine(card, i)}</span>
              </button>
            ),
          )}
          {!passOn ? (
            <button onClick={() => setPassOn(true)} className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink">
              <span className="text-ink-3">Or </span>pass it on to {card.approver || 'the approver'}
            </button>
          ) : (
            <div className="py-2">
              <p className="t-small text-ink-3">They get this brief:</p>
              <p className="t-small mt-1 text-ink-2">{tidy(card.escalation_brief)}</p>
              <div className="mt-3 flex flex-wrap items-center gap-4">
                <input
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="Add one line (optional)"
                  className="t-small h-10 min-w-0 flex-1 rounded-lg bg-soft px-3 focus:outline-2 focus:outline-accent"
                  aria-label="Note for the approver"
                />
                <button disabled={busy} onClick={escalate} className="t-small cursor-pointer font-medium text-accent hover:underline">Send</button>
                <button onClick={() => setPassOn(false)} className="t-small cursor-pointer text-ink-3 hover:text-ink">Cancel</button>
              </div>
            </div>
          )}
          <button disabled={busy} onClick={dismiss} className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink">
            <span className="text-ink-3">Or </span>dismiss: nothing to do
          </button>
          <button onClick={() => p.go(`/plan?card=${encodeURIComponent(card.id)}`)} className="t-small block cursor-pointer pt-2 text-left text-ink-3 hover:text-ink">
            Edit the message, all evidence and the trail in Plan
          </button>
        </div>
      )}

      <div ref={setLinesEl} />
      {actions}

      <SourceSheet card={card} claim={claim} index={source} anchors={anchors.items} ready={anchors.ready} onIndex={setSource} />
      {opt && (
        <EmailReview
          open={review}
          onOpenChange={setReview}
          to={opt.to ?? ''}
          toName={card.supplier_name ?? ''}
          subject={(opt as { subject?: string }).subject || headlineOf(card, state)}
          draft={draft}
          onDraft={setDraft}
          cost={money ? costLine(card, sel).replace(/\.$/, '') : null}
          busy={busy}
          error={error}
          onSend={() => { setReview(false); void approve(draft) }}
        />
      )}
    </article>
  )
}

// ---------------------------------------------------------------- email review

function EmailReview({
  open, onOpenChange, to, toName, subject, draft, onDraft, cost, busy, error, onSend,
}: {
  open: boolean; onOpenChange: (o: boolean) => void; to: string; toName: string; subject: string
  draft: string; onDraft: (t: string) => void; cost: string | null; busy: boolean; error: string; onSend: () => void
}) {
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fade fixed inset-0 z-40 bg-[rgba(24,24,26,.28)]" />
        <Dialog.Content
          aria-describedby={undefined}
          className={cn(
            'sheet-up fixed z-50 overflow-y-auto bg-ground focus:outline-none',
            'inset-x-0 bottom-0 max-h-[92vh] rounded-t-[22px] px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-3 shadow-[0_-10px_40px_-16px_rgba(0,0,0,.25)]',
            'md:inset-x-auto md:bottom-auto md:left-1/2 md:top-[8vh] md:max-h-[84vh] md:w-[640px] md:-translate-x-1/2 md:rounded-2xl md:px-8 md:pb-8 md:pt-7 md:shadow-[0_20px_60px_-20px_rgba(0,0,0,.3)]',
          )}
        >
          <div className="mx-auto mb-5 h-[5px] w-9 rounded-full bg-hair md:hidden" aria-hidden="true" />
          <Dialog.Title className="t-small font-normal text-ink-3">This email goes out when you press Send</Dialog.Title>
          <dl className="t-small mt-4 grid grid-cols-[64px_minmax(0,1fr)] gap-y-2 text-ink-2">
            <dt className="text-ink-3">To</dt>
            <dd className="min-w-0 break-words text-ink">{toName ? `${toName} · ` : ''}<span className="text-ink-2">{to}</span></dd>
            <dt className="text-ink-3">Subject</dt>
            <dd className="min-w-0 break-words text-ink">{subject}</dd>
          </dl>
          <label htmlFor="email-draft" className="sr-only">Email text</label>
          <textarea
            id="email-draft"
            value={draft}
            onChange={(e) => onDraft(e.target.value)}
            rows={10}
            className="t-body mt-4 w-full resize-y rounded-xl bg-soft p-4 leading-relaxed text-ink focus:outline-2 focus:outline-accent"
          />
          {cost && <p className="t-small mt-3 text-ink-2">This commits money: <span className="text-ink">{cost}</span>.</p>}
          {error && <p className="t-small mt-3 text-late" role="alert">{error}</p>}
          <div className="mt-6 flex items-center gap-6">
            <button
              onClick={onSend}
              disabled={busy || !draft.trim()}
              className="t-body inline-flex h-12 cursor-pointer items-center justify-center rounded-xl bg-accent px-7 font-medium text-white hover:bg-[#1d3db5] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60"
            >
              {busy ? 'Sending…' : 'Send email'}
            </button>
            <Dialog.Close className="t-body cursor-pointer text-ink-2 hover:text-ink">Cancel</Dialog.Close>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

function doneFrom(card: Card, i: number, status?: string): string {
  const a = actionText(card, i)
  const m = a.match(/^(\w+)\s+(.*)$/)
  const PAST: Record<string, string> = {
    ask: 'Asked', tell: 'Told', order: 'Ordered', send: 'Sent', book: 'Booked', collect: 'Collected', call: 'Called',
    move: 'Moved', release: 'Released', request: 'Requested', confirm: 'Confirmed', correct: 'Corrected', pay: 'Paid',
    accept: 'Accepted', cancel: 'Cancelled', expedite: 'Expedited', reserve: 'Reserved', notify: 'Notified', fly: 'Flew',
  }
  const past = m && PAST[m[1].toLowerCase()]
  // Short names and no order numbers: "Asked PackRight to make the order to rev C."
  const calm = (t: string) =>
    (card.supplier_name ? t.split(card.supplier_name).join(shortName(card.supplier_name)) : t).replace(/\bPO \d{6,}/g, 'the order')
  if (past) return calm(`${past} ${m![2]}`)
  return calm(status === 'sent' ? `Sent: ${a}` : `Approved: ${a}`)
}

const DbIcon = () => <Database aria-hidden="true" />
const DocIcon = () => <FileText aria-hidden="true" />

function ClaimLine({ claim, late, open, onOpen }: { claim: Claim; late: boolean; open: number | null; onOpen: (i: number) => void }) {
  return (
    <>
      {claim.pre}
      <button className="cite" aria-expanded={open === claim.sys.index} aria-haspopup="dialog" onClick={() => onOpen(claim.sys.index)}>
        {claim.sys.value}<DbIcon />
      </button>
      {claim.mid}
      <button className={cn('cite', late && 'late')} aria-expanded={open === claim.doc.index} aria-haspopup="dialog" onClick={() => onOpen(claim.doc.index)}>
        {claim.doc.value}<DocIcon />
      </button>
      {claim.post}
    </>
  )
}

/** A sentence whose numbers, when found in a source, open that source. */
function Cited({ text, anchors, onOpen, open }: { text: string; anchors: Record<number, Anchor[]> | null; onOpen: (i: number) => void; open: number | null }) {
  if (!text) return null
  const flat = Object.entries(anchors ?? {}).flatMap(([i, as]) => as.map((a) => ({ i: Number(i), a })))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(NUM_OR_ID)) {
    const hit = flat.find((x) => x.a.matched.includes(normTok(m[0])))
    if (!hit || !/\d/.test(m[0])) continue
    parts.push(text.slice(last, m.index))
    parts.push(
      <button key={m.index} className="cite" aria-expanded={open === hit.i} aria-haspopup="dialog" onClick={() => onOpen(hit.i)}>
        {m[0]}
      </button>,
    )
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

// ---------------------------------------------------------------- the source sheet

const SYS = /system|sap|erp/i
function sideLabel(card: Card, ev: Evidence): { who: string; isSys: boolean } {
  const isSys = SYS.test(ev.source ?? '')
  if (isSys) return { who: /\bSAP\b/.test(ev.source ?? '') ? 'SAP says' : 'The system says', isSys }
  const kind = docKind(ev.source) || 'the document'
  const owner = ev.doc?.startsWith('suppliers/') && card.supplier_name ? `${shortName(card.supplier_name)}'s ` : 'The '
  return { who: `${owner}${kind} says`.replace(/^The the/, 'The'), isSys }
}
const where = (a?: Anchor, ev?: Evidence) =>
  a ? (a.kind === 'table' || a.kind === 'text' ? `row ${(a.row ?? 0) + 1}` : `page ${a.page ?? 1}`) : ev?.page ? `page ${ev.page}` : ''

function SourceSheet({
  card, claim, index, anchors, ready, onIndex,
}: { card: Card; claim: Claim | null; index: number | null; anchors: Record<number, Anchor[]> | null; ready: boolean; onIndex: (i: number | null) => void }) {
  const ev = index != null ? card.evidence[index] : null
  const a = index != null ? anchors?.[index]?.[0] : undefined
  const otherIndex = claim && index != null ? (index === claim.sys.index ? claim.doc.index : index === claim.doc.index ? claim.sys.index : null) : null
  const other = otherIndex != null ? card.evidence[otherIndex] : null
  const otherA = otherIndex != null ? anchors?.[otherIndex]?.[0] : undefined
  const label = ev ? sideLabel(card, ev) : null
  const lang = ev ? languageOf(ev.source, ev.language) : null
  const head = ev
    ? [label!.isSys ? (/\bSAP\b/.test(ev.source ?? '') ? 'SAP' : 'System') : card.supplier_name, [docKind(ev.source), where(a, ev)].filter(Boolean).join(', '), lang]
        .filter(Boolean).join(' · ')
    : ''
  const english = ev?.translation ? ev.translation.split(' = ').pop() : null
  const original = a ? fileUrl(a) : ev?.doc ? `/api/file?path=${encodeURIComponent(ev.doc)}${ev.page ? `#page=${ev.page}` : ''}` : null

  return (
    <Dialog.Root open={index != null} onOpenChange={(o) => !o && onIndex(null)}>
      <Dialog.Portal>
        <Dialog.Overlay className="fade fixed inset-0 z-40 bg-[rgba(24,24,26,.28)]" />
        <Dialog.Content
          aria-describedby={undefined}
          className={cn(
            'sheet-up fixed z-50 overflow-y-auto bg-ground focus:outline-none',
            'inset-x-0 bottom-0 max-h-[88vh] rounded-t-[22px] px-6 pb-[max(36px,env(safe-area-inset-bottom))] pt-3 shadow-[0_-10px_40px_-16px_rgba(0,0,0,.25)]',
            'md:inset-x-auto md:bottom-auto md:left-1/2 md:top-[8vh] md:max-h-[84vh] md:w-[640px] md:-translate-x-1/2 md:rounded-2xl md:px-8 md:pb-8 md:pt-7 md:shadow-[0_20px_60px_-20px_rgba(0,0,0,.3)]',
          )}
        >
          <div className="mx-auto mb-5 h-[5px] w-9 rounded-full bg-hair md:hidden" aria-hidden="true" />
          {ev && (
            <>
              <Dialog.Title className="t-small font-normal text-ink-3">{head}</Dialog.Title>
              <div className="mt-3 overflow-hidden rounded-xl bg-soft p-3">
                {a ? (
                  <AnchorCrop key={`${index}-${a.doc}`} anchor={a} />
                ) : !ready ? (
                  <p className="t-small p-2 text-ink-3">Finding it in the documents…</p>
                ) : (
                  <p className="t-small whitespace-pre-wrap p-2 leading-[1.9] text-ink-2"><Marked text={tidy(ev.quote) || String(ev.value ?? '')} value={String(ev.value ?? '')} /></p>
                )}
              </div>
              {english ? (
                <p className="t-body mt-4 text-ink">{english}</p>
              ) : a && ev.quote ? (
                <p className="t-small mt-3 text-ink-3">{tidy(ev.quote)}</p>
              ) : null}

              {other && (
                <button
                  onClick={() => onIndex(otherIndex)}
                  className="t-body mt-7 grid w-full cursor-pointer grid-cols-[20px_1fr] gap-x-2.5 text-left text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
                >
                  <span className="mt-1 text-ink-3">{sideLabel(card, other).isSys ? <Database size={16} /> : <FileText size={16} />}</span>
                  <span>
                    <span className="font-medium text-ink">{sideLabel(card, other).who} {splitValue(other.value).big}</span>{' '}
                    {splitValue(other.value).rest}
                  </span>
                  <span className="t-small col-start-2 text-ink-3">{cap([docKind(other.source), where(otherA, other)].filter(Boolean).join(', '))}</span>
                </button>
              )}

              <div className="mt-7 flex items-center gap-4">
                {original && (
                  <a href={original} target="_blank" rel="noreferrer" className="t-small shrink-0 text-accent hover:underline">Open original</a>
                )}
                <Dialog.Close className="t-body h-[52px] flex-1 cursor-pointer rounded-[14px] bg-soft font-medium text-ink hover:bg-hair focus-visible:outline-2 focus-visible:outline-accent">
                  Back
                </Dialog.Close>
              </div>
            </>
          )}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/** The quote with the value's numbers highlighted (when no page or row was found). */
function Marked({ text, value }: { text: string; value: string }) {
  const nums = new Set((value.match(/\d[\d,.]*\d|\d/g) ?? []).map(normTok))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(/\d[\d,.]*\d|\d/g)) {
    if (!nums.has(normTok(m[0]))) continue
    parts.push(text.slice(last, m.index), <mark key={m.index} className="rounded-[3px] bg-mark px-1 font-semibold text-[#111]">{m[0]}</mark>)
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

// ---------------------------------------------------------------- done

function DoneView(p: Props & { done: DoneInfo }) {
  const { done, state, phone } = p
  const live = useLive()
  const outcome = done.actionId ? live.undo[done.actionId] : undefined
  const [undoing, setUndoing] = useState(false)
  const next = p.order.find((c) => c.id !== done.card.id) ?? null
  const offer = done.offer > 0 && !outcome?.ok
  const who = shortName(done.card.supplier_name)

  const undo = async () => {
    if (!done.actionId) return
    setUndoing(true)
    const r = await undoAction(done.actionId)
    setUndoing(false)
    if (r.ok) p.onChanged()
  }

  const primary = offer
    ? { label: 'Show me how', onClick: () => { p.onRoutines({ cardId: done.card.id, k: Date.now() }); p.onClearDone() } }
    : next
      ? { label: 'Next decision', onClick: () => { p.onFocus(next.id); p.onClearDone() } }
      : null
  const quiet = offer ? { label: 'Not now', onClick: p.onClearDone } : null

  return (
    <section className="rise" aria-live="polite">
      <div className="mb-6 grid h-10 w-10 place-items-center rounded-full bg-soft text-ink"><Check size={20} strokeWidth={1.75} /></div>
      <h1 className="t-big text-ink">{outcome?.ok ? 'Undone.' : `Done. ${done.text}`}</h1>
      <p className="t-body mt-6 text-ink-2">
        {outcome?.ok ? 'It is back on your list.' : done.sub}{' '}
        {done.actionId && !outcome && (
          <button onClick={undo} disabled={undoing} className="uline">{undoing ? 'Undoing…' : 'Undo'}</button>
        )}
        {outcome && !outcome.ok && <span className="t-small block pt-2 text-ink-3">Undo: {outcome.reason}

content.content:
  const { state, nowMs, phone, card, done } = p
  const handled = routineCount(state, nowMs)
  const view = done ? 'done' : card ? 'decide' : 'clear'

  const foot = (
    <FootLines state={state} handled={handled} pending={p.pending} onRoutines={() => p.onRoutines()} go={p.go} nowMs={nowMs} center={!phone} />
  )

  const body =
    view === 'done' ? (
      <DoneView key={`done-${done!.k}`} {...p} done={done!} />
    ) : view === 'decide' ? (
      <Focus key={card!.id} {...p} card={card!} />
    ) : (
      <AllClear state={state} nowMs={nowMs} handled={handled} pending={p.pending} onRoutines={p.onRoutines} go={p.go} />
    )

  if (phone) {
    return (
      <main className="mx-auto w-full max-w-[560px] px-7 pb-[220px] pt-5">
        {body}
        {view === 'decide' && (handled > 0 || p.pending > 0) && <div className="mt-14">{foot}</div>}
      </main>
    )
  }
  // Desktop: a very quiet list on the left, the decision in a 640 px column.
  return (
    <div className="relative flex-1">
      <div className="mx-auto grid w-full max-w-[1440px] grid-cols-[240px_minmax(0,640px)] gap-x-16 px-12 pb-32 pt-24 xl:grid-cols-[300px_640px] xl:gap-x-[124px] xl:px-24">
        <aside aria-label="Needs you">
          {p.order.length > 0 && <QuietList {...p} />}
        </aside>
        <main className="min-w-0">{body}</main>
      </div>
      {view !== 'clear' && <div className="fixed inset-x-0 bottom-8 z-10 flex justify-center">{foot}</div>}
    </div>
  )
}

// ---------------------------------------------------------------- left list

function QuietList({ order, card, onFocus, state, nowMs }: Props) {
  // One line per problem: look-alikes fold into their first card.
  const seen = new Map<string, { c: Card; n: number }>()
  for (const c of order) {
    const k = `${c.supplier_id ?? c.supplier_name}|${c.kind}|${shortTitle(c, state).replace(/\d[\d,.]*/g, '#')}`
    const e = seen.get(k)
    if (e) e.n += 1
    else seen.set(k, { c, n: 1 })
  }
  const rows = [...seen.values()]
  const shown = rows.slice(0, 5)
  const more = rows.slice(5).reduce((n, r) => n + r.n, 0)
  return (
    <div>
      <p className="t-small mb-3 text-ink-3">Needs you</p>
      <ul className="-mx-3.5">
        {shown.map(({ c, n }) => {
          const on = card?.id === c.id
          return (
            <li key={c.id}>
              <button
                onClick={() => onFocus(c.id)}
                aria-current={on ? 'true' : undefined}
                className={cn(
                  't-small grid w-full cursor-pointer grid-cols-[8px_1fr_auto] items-baseline gap-3.5 rounded-[10px] px-3.5 py-3 text-left focus-visible:outline-2 focus-visible:outline-accent',
                  on ? 'bg-soft font-medium text-ink' : 'text-ink-2 hover:text-ink',
                )}
              >
                <i className={cn('h-[7px] w-[7px] -translate-y-px rounded-full', on ? 'bg-accent' : 'bg-ink-3')} />
                <span className="truncate">{shortTitle(c, state)}{n > 1 && <span className="font-normal text-ink-3"> · {n}</span>}</span>
                <span className="font-normal text-ink-3">{c.deadline ? when(c.deadline, nowMs) : ''}</span>
              </button>
            </li>
          )
        })}
      </ul>
      {more > 0 && <p className="t-small mt-2 text-ink-3">+{more} more</p>}
      <p className="t-small mt-6 text-ink-3"><kbd>J</kbd> <kbd>K</kbd> to move, <kbd>A</kbd> to approve</p>
    </div>
  )
}

// ---------------------------------------------------------------- one decision

function Focus(p: Props & { card: Card }) {
  const { card, state, nowMs, phone } = p
  const [sel, setSel] = useState(() => recommendedIndex(card))
  const [confirm, setConfirm] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [others, setOthers] = useState(false)
  const [passOn, setPassOn] = useState(false)
  const [note, setNote] = useState('')
  const [source, setSource] = useState<number | null>(null)
  // An email to a supplier is shown before it goes out: it cannot be taken back.
  const [review, setReview] = useState(false)
  const [draft, setDraft] = useState('')
  const [linesEl, setLinesEl] = useState<HTMLDivElement | null>(null)
  const anchors = useAnchors(card.id)
  const claim = claimOf(card)
  const today = forToday(card, state, nowMs)
  const opt = card.options[sel]
  const recommended = sel === recommendedIndex(card)
  const money = opt ? costsMoney(card, sel) : false
  const emails = !!opt && opt.channel === 'email' && /@/.test(opt.to ?? '')
  const late = card.level === 'red'

  async function act(fn: () => Promise<{ text: string; sub: string; actionId: string | null }>) {
    setBusy(true); setError('')
    try {
      const out = await fn()
      p.onDone({ card, ...out })
      p.onChanged()
    } catch (e) {
      setError(`That did not go through: ${(e as Error).message}. Nothing was sent.`)
    } finally { setBusy(false); setConfirm(false) }
  }
  const approve = (text?: string) =>
    act(async () => {
      const edited = text != null && text.trim() !== (opt?.draft ?? '').trim()
      const r = await post<{ action?: { id?: string; status?: string } }>(
        `/api/cards/${encodeURIComponent(card.id)}/approve`,
        edited ? { option: sel, text } : { option: sel },
      )
      const status = r.action?.status
      const at = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
      const sent = status === 'sent'
      const sub = sent
        ? `Sent to ${shortName(card.supplier_name) || opt?.to} at ${at}. You'll see the reply here.`
        : opt?.channel === 'notify' && opt.to ? `${opt.to} has it now.` : 'Recorded.'
      // A sent email cannot be undone, so no Undo is offered for it.
      return { text: doneFrom(card, sel, status), sub, actionId: sent ? null : r.action?.id ?? null }
    })
  const openReview = () => { setDraft(opt?.draft ?? ''); setReview(true) }
  const escalate = () =>
    act(async () => {
      const r = await post<{ id?: string }>(`/api/cards/${encodeURIComponent(card.id)}/escalate`, { note })
      return { text: `Passed on to ${card.approver || 'the approver'}.`, sub: 'You will see their answer here.', actionId: r?.id ?? null }
    })
  const dismiss = () =>
    act(async () => {
      const r = await post<{ id?: string }>(`/api/cards/${encodeURIComponent(card.id)}/dismiss`)
      return { text: 'Taken off the list.', sub: 'Nothing was sent.', actionId: r?.id ?? null }
    })
  const onApprove = () => (emails ? openReview() : money ? setConfirm(true) : void approve())

  // Keyboard (desktop): j/k walk, a asks, Enter approves, Esc cancels.
  const ref = useRef({ approve, confirm, busy, emails, openReview })
  ref.current = { approve, confirm, busy, emails, openReview }
  useEffect(() => {
    if (phone) return
    const onKey = (e: KeyboardEvent) => {
      if (typing(e.target) || e.metaKey || e.ctrlKey || e.altKey || source != null || review) return
      const k = e.key
      if (ref.current.confirm && k === 'Enter') { e.preventDefault(); void ref.current.approve() }
      else if (k === 'Escape') { setConfirm(false); setOthers(false) }
      else if ((k === 'a' || k === 'A') && opt && !ref.current.busy) {
        e.preventDefault()
        if (ref.current.emails) ref.current.openReview()
        else setConfirm(true)
      }
      else if (k === 'j' || k === 'k' || k === 'ArrowDown' || k === 'ArrowUp') {
        const i = p.order.findIndex((c) => c.id === card.id)
        const n = p.order[Math.min(p.order.length - 1, Math.max(0, i + (k === 'j' || k === 'ArrowDown' ? 1 : -1)))]
        if (n && n.id !== card.id) { e.preventDefault(); p.onFocus(n.id) }
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [phone, source, review, opt, card.id, p])

  const decideBy = card.deadline ? (new Date(card.deadline).getTime() <= nowMs ? 'decide now' : `decide by ${when(card.deadline, nowMs)}`) : ''
  const meta = [card.supplier_name || card.part_name, decideBy].filter(Boolean).join(' · ')

  const actions = opt && (
    <div className={cn(phone ? 'fixed inset-x-0 bottom-0 z-20 bg-gradient-to-t from-ground from-70% to-ground/0 px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-8' : 'mt-8')}>
      <div className={cn(phone && 'mx-auto max-w-[520px]')}>
        {confirm && (
          <p className={cn('t-small mb-3 text-ink-2', phone && 'text-center')} role="alert">
            Approve: <span className="text-ink">{actionText(card, sel).replace(/\.$/, '')}</span> ({costLine(card, sel).replace(/\.$/, '')})
            {!phone && <span className="text-ink-3"> · <kbd>Enter</kbd> confirms</span>}
          </p>
        )}
        {error && <p className="t-small mb-3 text-late" role="alert">{error}</p>}
        <div className={cn(phone ? 'grid justify-items-center gap-3.5' : 'flex flex-wrap items-center gap-6', p.ringing && phone && 'gap-5')}>
          <button
            onClick={confirm ? () => approve() : onApprove}
            disabled={busy}
            className={cn(
              'inline-flex cursor-pointer items-center justify-center rounded-xl font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60 t-body',
              // While the alert rings, Answer is the one blue button.
              p.ringing ? 'bg-soft text-ink hover:bg-hair' : 'bg-accent text-white shadow-[0_1px_2px_rgba(35,72,208,.25)] hover:bg-[#1d3db5]',
              phone ? 'h-[54px] w-full rounded-[14px]' : 'h-12 px-7',
            )}
          >
            {busy ? 'Sending…' : confirm ? 'Yes, approve' : emails ? 'Review email' : 'Approve'}
          </button>
          <div className={cn('flex items-center', phone ? 't-small gap-7' : 't-body gap-6', p.ringing && 'order-first w-full flex-col gap-4 pb-2 lg:items-start')}>
            <VoiceCall card={card} onChanged={p.onChanged} ringing={p.ringing} onRingingDone={p.onRingingDone} quiet linesEl={linesEl} />
            {confirm ? (
              <button onClick={() => setConfirm(false)} className="cursor-pointer text-ink-2 hover:text-ink">Cancel</button>
            ) : (
              <button onClick={() => setOthers(!others)} aria-expanded={others} className="cursor-pointer text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-accent">
                {others ? 'Fewer options' : 'Other options'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  )

  return (
    <article className="rise" aria-label={headlineOf(card, state)}>
      <p className="t-small mb-4 text-ink-3">{meta}</p>
      <h1 className="t-big text-ink">{headlineOf(card, state)}</h1>

      <p className="t-body mt-6 text-ink-2">
        {claim ? (
          <ClaimLine claim={claim} late={late} open={source} onOpen={setSource} />
        ) : (
          <Cited text={summaryLine(card)} anchors={anchors.items} onOpen={setSource} open={source} />
        )}
      </p>
      {today && (
        <p className="t-body mt-4 text-ink-2">For today: <span className="font-medium text-ink">{today.bold}</span>{today.rest}</p>
      )}

      {opt && (
        <div className={cn(phone ? 'mt-9' : 'mt-12')}>
          <p className="t-small mb-1.5 text-ink-3">{recommended ? 'We recommend' : 'Your choice'}</p>
          <p className="t-body text-ink">{actionText(card, sel)}{phone && <span className="text-ink-2"> {costLine(card, sel)}</span>}</p>
          {!phone && (
            <p className="t-body text-ink-2">{costLine(card, sel)}{opt.effect ? ` ${cap(tidy(opt.effect))}.`.replace(/\.\.$/, '.') : ''}</p>
          )}
        </div>
      )}

      {others && (
        <div className="fade mt-8 space-y-1" aria-label="Other options">
          {card.options.map((_, i) =>
            i === sel ? null : (
              <button
                key={i}
                onClick={() => { setSel(i); setOthers(false); setConfirm(false) }}
                className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
              >
                <span className="text-ink-3">Or </span>{actionText(card, i).replace(/^./, (c) => c.toLowerCase())}{' '}
                <span className="t-small text-ink-3">{costLine(card, i)}</span>
              </button>
            ),
          )}
          {!passOn ? (
            <button onClick={() => setPassOn(true)} className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink">
              <span className="text-ink-3">Or </span>pass it on to {card.approver || 'the approver'}
            </button>
          ) : (
            <div className="py-2">
              <p className="t-small text-ink-3">They get this brief:</p>
              <p className="t-small mt-1 text-ink-2">{tidy(card.escalation_brief)}</p>
              <div className="mt-3 flex flex-wrap items-center gap-4">
                <input
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="Add one line (optional)"
                  className="t-small h-10 min-w-0 flex-1 rounded-lg bg-soft px-3 focus:outline-2 focus:outline-accent"
                  aria-label="Note for the approver"
                />
                <button disabled={busy} onClick={escalate} className="t-small cursor-pointer font-medium text-accent hover:underline">Send</button>
                <button onClick={() => setPassOn(false)} className="t-small cursor-pointer text-ink-3 hover:text-ink">Cancel</button>
              </div>
            </div>
          )}
          <button disabled={busy} onClick={dismiss} className="t-body block w-full cursor-pointer py-2 text-left text-ink-2 hover:text-ink">
            <span className="text-ink-3">Or </span>dismiss: nothing to do
          </button>
          <button onClick={() => p.go(`/plan?card=${encodeURIComponent(card.id)}`)} className="t-small block cursor-pointer pt-2 text-left text-ink-3 hover:text-ink">
            Edit the message, all evidence and the trail in Plan
          </button>
        </div>
      )}

      <div ref={setLinesEl} />
      {actions}

      <SourceSheet card={card} claim={claim} index={source} anchors={anchors.items} ready={anchors.ready} onIndex={setSource} />
      {opt && (
        <EmailReview
          open={review}
          onOpenChange={setReview}
          to={opt.to ?? ''}
          toName={card.supplier_name ?? ''}
          subject={(opt as { subject?: string }).subject || headlineOf(card, state)}
          draft={draft}
          onDraft={setDraft}
          cost={money ? costLine(card, sel).replace(/\.$/, '') : null}
          busy={busy}
          error={error}
          onSend={() => { setReview(false); void approve(draft) }}
        />
      )}
    </article>
  )
}

