import { ExternalLink } from 'lucide-react'
import { useEffect, useState } from 'react'
import { type Anchor, AnchorList, CitedText, OpenAnchor, useAnchors } from '@/components/SourceAnchors'
import { Sheet, SheetContent, SheetDescription, SheetTitle } from '@/components/ui/sheet'
import { fmtDay, fmtTime, tidy, type Card } from '@/lib/api'

export type DrawerView = { card: Card; tab: 'evidence' | 'trail' } | null

export function EvidenceDrawer({ view, onClose }: { view: DrawerView; onClose: () => void }) {
  const card = view?.card
  return (
    <Sheet open={!!view} onOpenChange={(o) => !o && onClose()}>
      {card && view && (
        <SheetContent>
          <div className="border-b border-line px-6 pb-4 pt-6 pr-14">
            <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">
              {view.tab === 'evidence' ? 'Evidence' : 'Agent trail'}
            </div>
            <SheetTitle className="mt-1 text-xl font-bold leading-snug">{card.headline}</SheetTitle>
            <SheetDescription className="sr-only">Source documents and agent steps behind this decision</SheetDescription>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
            {view.tab === 'evidence' ? <Evidence card={card} /> : <Trail card={card} />}
          </div>
        </SheetContent>
      )}
    </Sheet>
  )
}

const SYSTEM = /system|sap|erp|plan|book stock/i
const PAPER = /paper|document|scan|advice|confirmation|delivery note|notice|invoice/i

function Evidence({ card }: { card: Card }) {
  const anchors = useAnchors(card.id)
  const [open, setOpen] = useState<Anchor | null>(null)
  if (!card.evidence.length) return <p className="text-ink-2">No source documents attached to this decision yet.</p>
  // Lead with the contradiction: what the system says against what the paper says, each with its
  // source opened at the spot. Everything else follows as supporting evidence.
  const sys = card.evidence.findIndex((e) => SYSTEM.test(e.source ?? ''))
  const paper = card.evidence.findIndex((e, i) => i !== sys && PAPER.test(e.source ?? ''))
  const pair = sys >= 0 && paper >= 0 ? [sys, paper] : []
  const rest = card.evidence.map((_, i) => i).filter((i) => !pair.includes(i))
  const order = [...pair, ...rest]
  const all = order.flatMap((i) => anchors.items?.[i] ?? [])
  const point = card.summary || card.reason
  return (
    <>
      {point && (
        <div>
          <p className="text-[17px] leading-relaxed text-ink">
            <CitedText text={point} anchors={all} active={open} onOpen={setOpen} />
          </p>
          <OpenAnchor anchor={open} />
        </div>
      )}
      {pair.length > 0 && (
        <div className="space-y-2">
          <Side e={card.evidence[sys]} tone="system" anchors={anchors.items?.[sys]} ready={anchors.ready} />
          <div className="flex items-center gap-2 px-1 text-sm font-bold text-stop">
            <span className="h-px flex-1 bg-stop/30" /> does not match <span className="h-px flex-1 bg-stop/30" />
          </div>
          <Side e={card.evidence[paper]} tone="paper" anchors={anchors.items?.[paper]} ready={anchors.ready} />
        </div>
      )}
      {rest.length > 0 && (
        <>
          {pair.length > 0 && <div className="pt-2 text-xs font-semibold uppercase tracking-wide text-ink-3">More evidence</div>}
          {rest.map((i) => (
            <EvidenceItem key={i} e={card.evidence[i]} anchors={anchors.items?.[i]} ready={anchors.ready} />
          ))}
        </>
      )}
    </>
  )
}

/** One supporting evidence line: its value, the quote and translation, and where it was found. */
export function EvidenceItem({ e, anchors, ready }: { e: Card['evidence'][number]; anchors?: Anchor[]; ready: boolean }) {
  return (
    <section className="rounded-xl border border-line p-4">
      <div className="flex items-baseline justify-between gap-3">
        <div className="text-[15px] font-semibold">{e.source && !/^evidence$/i.test(e.source) ? tidy(e.source) : 'Supporting note'}</div>
        {e.value != null && String(e.value).length <= 24 && <div className="text-xl font-extrabold tabular-nums">{typeof e.value === 'number' ? e.value.toLocaleString('en-GB') : tidy(e.value)}</div>}
      </div>
      {e.value != null && String(e.value).length > 24 && <p className="mt-1.5 text-[15px] font-semibold text-ink">{tidy(String(e.value))}</p>}
      {e.quote && (
        <blockquote className="mt-3 border-l-4 border-line pl-3 text-[15px] text-ink">
          “{e.quote}”
          {e.language && <span className="ml-2 text-xs uppercase text-ink-3">{e.language}</span>}
        </blockquote>
      )}
      {e.translation && <p className="mt-2 text-sm text-ink-2">In English: {e.translation}</p>}
      {e.doc && !anchors?.length && (
        <a
          href={`/api/file?path=${encodeURIComponent(e.doc)}${e.page ? `#page=${e.page}` : ''}`}
          target="_blank"
          rel="noreferrer"
          className="mt-3 inline-flex items-center gap-1.5 text-sm font-semibold text-ok hover:underline"
        >
          Open source document{e.page ? `, page ${e.page}` : ''} <ExternalLink size={14} />
        </a>
      )}
      <AnchorList anchors={anchors} ready={ready} />
    </section>
  )
}

export function Side({ e, tone, anchors, ready }: {
  e: Card['evidence'][number]; tone: 'system' | 'paper'; anchors?: Anchor[]; ready: boolean
}) {
  const [open, setOpen] = useState<Anchor | null>(null)
  const list = anchors ?? []
  const first = list[0]
  useEffect(() => {
    if (tone === 'paper' && first) setOpen((o) => o ?? first) // show the document right away
  }, [tone, first])
  const cited = (t: string) => <CitedText text={t} anchors={list} active={open} onOpen={setOpen} />
  return (
    <section className={tone === 'system' ? 'rounded-xl border border-line bg-panel p-4' : 'rounded-xl border-2 border-stop/40 bg-white p-4'}>
      <div className="text-xs font-bold uppercase tracking-wide text-ink-3">{tone === 'system' ? 'The system says' : 'The document says'}</div>
      <div className="mt-1 text-[22px] font-extrabold leading-tight tabular-nums">{tidy(String(e.value ?? ''))}</div>
      <div className="mt-1 text-sm text-ink-2">{e.source?.replace(/^(System|Paper) says\s*·\s*/i, '')}</div>
      {e.quote && <blockquote className="mt-2 border-l-4 border-line pl-3 text-sm leading-relaxed text-ink">“{cited(String(e.quote))}”</blockquote>}
      {e.translation && <p className="mt-1.5 text-sm text-ink-2">In English: {e.translation}</p>}
      <OpenAnchor anchor={open} />
      {list.length === 0 && <AnchorList anchors={anchors} ready={ready} />}
    </section>
  )
}

export function Trail({ card }: { card: Card }) {
  if (!card.trail.length) return <p className="text-ink-2">No agent steps recorded for this decision yet.</p>
  return (
    <ol className="space-y-4">
      {card.trail.map((t, i) => (
        <li key={i} className="relative border-l-2 border-line pl-4">
          <span className="absolute -left-[5px] top-1.5 h-2 w-2 rounded-full bg-ok" />
          <div className="text-sm font-semibold">
            {t.agent}
            {t.at && <span className="ml-2 font-normal text-ink-3">{fmtDay(t.at)} {fmtTime(t.at)}</span>}
          </div>
          <div className="text-[15px] text-ink-2">{t.text}</div>
        </li>
      ))}
    </ol>
  )
}
import { ExternalLink, FileText, Image as ImageIcon, Table } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

// Where an evidence line was found in the portal documents (anchors.py): the PDF page or scan
// with the matched words highlighted, or the spreadsheet row. Opens inline, original one tap away.

export interface Anchor {
  doc: string
  kind: 'pdf' | 'image' | 'table' | 'text'
  page?: number
  row?: number
  sheet?: string
  score: number
  matched: string[]
  boxes?: [number, number, number, number][]
  snippet?: string
  source?: 'text' | 'ocr'
}
type Items = Record<number, Anchor[]>

export function useAnchors(cardId: string): { items: Items | null; ready: boolean } {
  const [items, setItems] = useState<Items | null>(null)
  const [ready, setReady] = useState(true)
  useEffect(() => {
    let stop = false
    let timer: number | undefined
    const load = async () => {
      try {
        const r = await fetch(`/api/anchors/${encodeURIComponent(cardId)}`)
        if (!r.ok) return
        const d = (await r.json()) as { ready: boolean; items: { evidence: number; anchors: Anchor[] }[] }
        if (stop) return
        setItems(Object.fromEntries(d.items.map((x) => [x.evidence, x.anchors])))
        setReady(d.ready)
        if (!d.ready) timer = window.setTimeout(load, 4000) // index still building
      } catch {
        /* sources are optional */
      }
    }
    void load()
    return () => {
      stop = true
      clearTimeout(timer)
    }
  }, [cardId])
  return { items, ready }
}

const name = (doc: string) => doc.split('/').pop() ?? doc
export const fileUrl = (a: Anchor) =>
  `/api/file?path=${encodeURIComponent(a.doc)}${a.kind === 'pdf' && a.page ? `#page=${a.page}` : ''}`

export function AnchorList({
  anchors, ready, defaultOpen = null,
}: { anchors?: Anchor[]; ready: boolean; defaultOpen?: number | null }) {
  const [open, setOpen] = useState<number | null>(defaultOpen)
  if (!anchors) return null
  if (!anchors.length) {
    return ready ? null : <p className="mt-3 text-sm text-ink-3">Looking for this in the documents…</p>
  }
  return (
    <div className="mt-3">
      <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">Found in</div>
      <div className="mt-1.5 flex flex-wrap gap-1.5">
        {anchors.map((a, i) => {
          const Icon = a.kind === 'table' ? Table : a.kind === 'image' ? ImageIcon : FileText
          const where = a.kind === 'table' || a.kind === 'text' ? `row ${(a.row ?? 0) + 1}` : `page ${a.page}`
          return (
            <button
              key={i}
              onClick={() => setOpen(open === i ? null : i)}
              className={cn(
                'inline-flex max-w-full cursor-pointer items-center gap-1.5 rounded-full border px-3 py-1 text-sm',
                open === i ? 'border-ok bg-ok/10 font-semibold text-ok' : 'border-line text-ink-2 hover:bg-panel',
              )}
              title={a.doc}
            >
              <Icon size={14} className="shrink-0" />
              <span className="truncate">{name(a.doc)}</span>
              <span className="shrink-0 text-ink-3">· {where}{a.source === 'ocr' ? ' · scan' : ''}</span>
            </button>
          )
        })}
      </div>
      {open != null && anchors[open] && <AnchorView anchor={anchors[open]} />}
    </div>
  )
}

/** Just the highlighted crop (page, scan, table row or text), no links: for the source sheet. */
export function AnchorCrop({ anchor: a }: { anchor: Anchor }) {
  return a.kind === 'table' ? <TableView a={a} /> : a.kind === 'text' ? <TextView a={a} /> : <PageView a={a} />
}

function AnchorView({ anchor: a }: { anchor: Anchor }) {
  return (
    <div className="mt-3 rounded-lg border border-line bg-panel p-2">
      {a.kind === 'table' ? <TableView a={a} /> : a.kind === 'text' ? <TextView a={a} /> : <PageView a={a} />}
      <a
        href={fileUrl(a)}
        target="_blank"
        rel="noreferrer"
        className="mt-2 inline-flex items-center gap-1.5 px-1 text-sm font-semibold text-ok hover:underline"
      >
        Open original <ExternalLink size={14} />
      </a>
    </div>
  )
}

function PageView({ a }: { a: Anchor }) {
  // Zoomed in on the highlighted values (with some context), full page one tap away. No
  // scrollIntoView: it would scroll the whole drawer away from the point being made.
  const [size, setSize] = useState<{ w: number; h: number } | null>(null)
  const [full, setFull] = useState(false)
  const boxes = a.boxes ?? []
  const src = `/api/doc/page?path=${encodeURIComponent(a.doc)}&page=${a.page ?? 1}`
  let crop = { x0: 0, y0: 0, x1: 1, y1: 1 }
  if (boxes.length && !full) {
    const x0 = Math.min(...boxes.map((b) => b[0])), x1 = Math.max(...boxes.map((b) => b[2]))
    const y0 = Math.min(...boxes.map((b) => b[1])), y1 = Math.max(...boxes.map((b) => b[3]))
    const cx = (x0 + x1) / 2, w = Math.max(0.5, x1 - x0 + 0.12)
    const left = Math.min(Math.max(0, cx - w / 2), 1 - Math.min(1, w))
    crop = { x0: left, x1: Math.min(1, left + w), y0: Math.max(0, y0 - 0.05), y1: Math.min(1, y1 + 0.05) }
  }
  const cw = crop.x1 - crop.x0, ch = crop.y1 - crop.y0
  return (
    <div>
      <div
        className="relative overflow-hidden rounded bg-white"
        style={size ? { aspectRatio: `${cw * size.w} / ${ch * size.h}` } : { minHeight: 120 }}
      >
        <div
          className="absolute"
          style={{ width: `${100 / cw}%`, height: `${100 / ch}%`, left: `${(-crop.x0 / cw) * 100}%`, top: `${(-crop.y0 / ch) * 100}%` }}
        >
          <img
            src={src}
            alt={name(a.doc)}
            className="block h-full w-full"
            onLoad={(e) => setSize({ w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight })}
          />
          {size &&
            boxes.map(([x0, y0, x1, y1], i) => (
              <div
                key={i}
                className="absolute rounded-[2px] bg-mark/60 mix-blend-multiply"
                style={{
                  left: `${x0 * 100 - 0.3}%`,
                  top: `${y0 * 100 - 0.25}%`,
                  width: `${(x1 - x0) * 100 + 0.6}%`,
                  height: `${(y1 - y0) * 100 + 0.5}%`,
                }}
              />
            ))}
        </div>
      </div>
      {boxes.length > 0 && (
        <button className="mt-2 cursor-pointer px-1 text-[13px] text-ink-3 hover:text-ink" onClick={() => setFull(!full)}>
          {full ? 'Zoom to the values' : 'Show full page'}
        </button>
      )}
    </div>
  )
}

function TableView({ a }: { a: Anchor }) {
  const [data, setData] = useState<{ header: string[]; rows: { row: number; cells: string[]; hit: boolean }[] } | null>(null)
  const hit = useRef<HTMLTableRowElement | null>(null)
  useEffect(() => {
    const q = new URLSearchParams({ path: a.doc, row: String(a.row ?? 0), sheet: a.sheet ?? '' })
    fetch(`/api/doc/table?${q}`).then((r) => (r.ok ? r.json() : null)).then(setData).catch(() => setData(null))
  }, [a.doc, a.row, a.sheet])
  const box = useRef<HTMLDivElement | null>(null)
  useEffect(() => {
    const el = hit.current, wrap = box.current
    if (el && wrap) wrap.scrollTop = el.offsetTop - wrap.clientHeight / 2
  }, [data])
  if (!data) return <p className="p-2 text-sm text-ink-3">Loading table…</p>
  const wanted = new Set(a.matched)
  const norm = (s: string) => s.replace(/(?<=\d)[,.' ](?=\d{3}(?!\d))/g, '').toUpperCase()
  return (
    <div ref={box} className="relative max-h-[40vh] overflow-auto rounded bg-white">
      {a.sheet && <div className="px-2 pt-2 text-xs font-semibold text-ink-3">Sheet: {a.sheet}</div>}
      <table className="w-full border-collapse text-[13px] tabular-nums">
        <thead className="sticky top-0 bg-panel">
          <tr>{data.header.map((h, i) => <th key={i} className="whitespace-nowrap border-b border-line px-2 py-1 text-left font-semibold text-ink-2">{h}</th>)}</tr>
        </thead>
        <tbody>
          {data.rows.map((r) => (
            <tr key={r.row} ref={r.hit ? hit : undefined} className={r.hit ? 'bg-mark/25' : ''}>
              {r.cells.map((c, i) => (
                <td
                  key={i}
                  className={cn(
                    'whitespace-nowrap border-b border-line px-2 py-1',
                    r.hit && [...wanted].some((w) => norm(c).includes(w)) && 'bg-mark font-semibold text-ink',
                  )}
                >
                  {c}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function TextView({ a }: { a: Anchor }) {
  return <p className="whitespace-pre-wrap break-words rounded bg-mark/30 p-2 font-mono text-[13px]">{a.snippet}</p>
}

// ---------------------------------------------------------------- inline citations

export const NUM_OR_ID = /[A-Za-z]*\d[\d,.' ]*\d(?:[-_/][A-Za-z0-9]+)*|[A-Za-z]+[-_]?\d{3,}[A-Za-z0-9-]*/g
export const normTok = (s: string) => s.replace(/(?<=\d)[,.'  ](?=\d{3}(?!\d))/g, '').toUpperCase()

// 'purchase_orders_2025H2-2026.csv' -> 'purchase orders': the words of the file name, no ids or dates
const label = (doc: string) =>
  name(doc).replace(/\.[a-z0-9]+$/i, '').split(/[_\s-]+/).filter((w) => w && !/\d/.test(w)).join(' ').toLowerCase() || name(doc)
const tag = (a: Anchor) =>
  a.kind === 'table' || a.kind === 'text'
    ? `${label(a.doc)} · row ${(a.row ?? 0) + 1}`
    : `${a.kind === 'image' || a.source === 'ocr' ? 'scan' : 'PDF'} · p. ${a.page ?? 1}`

/**
 * Text with every number or id that the agent found in a source turned into a citation chip.
 * `anchors` are tried in order, so pass the preferred source first.
 */
export function CitedText({
  text, anchors, active, onOpen, className,
}: {
  text: string
  anchors: Anchor[]
  active?: Anchor | null
  onOpen: (a: Anchor | null) => void
  className?: string
}) {
  const parts: (string | { raw: string; a: Anchor })[] = []
  let last = 0
  for (const m of text.matchAll(NUM_OR_ID)) {
    const a = anchors.find((x) => x.matched.includes(normTok(m[0])))
    if (!a) continue
    parts.push(text.slice(last, m.index), { raw: m[0], a })
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return (
    <span className={className}>
      {parts.map((p, i) =>
        typeof p === 'string' ? (
          <span key={i}>{p}</span>
        ) : (
          <button
            key={i}
            onClick={() => onOpen(active === p.a ? null : p.a)}
            title={`Found in ${p.a.doc}`}
            className={cn(
              'mx-0.5 inline-flex cursor-pointer items-baseline gap-1 rounded-md px-1.5 align-baseline font-bold underline decoration-dotted underline-offset-4',
              active === p.a ? 'bg-yellow-300/70 text-ink' : 'bg-yellow-100 text-ink hover:bg-yellow-200',
            )}
          >
            {p.raw}
            <span className="whitespace-nowrap text-[11px] font-semibold text-ink-3 no-underline">{tag(p.a)}</span>
          </button>
        ),
      )}
    </span>
  )
}

export function OpenAnchor({ anchor }: { anchor: Anchor | null }) {
  return anchor ? <AnchorView anchor={anchor} /> : null
}
import { Bell, BellRing } from 'lucide-react'
import { useEffect, useState } from 'react'
import { enableAlerts, pushSupported, registerServiceWorker, sendTestAlert } from '@/lib/push'

// Launch alerts on this device (web push). Independent of the cards on screen, so a fresh
// visit with an empty inbox can still turn them on.
export function AlertsButton() {
  const [on, setOn] = useState(false)
  const [info, setInfo] = useState('')
  const supported = pushSupported()

  useEffect(() => {
    void registerServiceWorker().then(async (reg) => {
      const sub = await reg?.pushManager.getSubscription()
      setOn(!!sub && Notification.permission === 'granted')
    })
  }, [])

  const say = (text: string) => {
    setInfo(text)
    window.setTimeout(() => setInfo(''), 6000)
  }

  return (
    <div className="relative">
      {info && (
        <div className="absolute right-0 top-11 z-50 w-72 rounded-xl bg-white px-4 py-3 text-[13.5px] text-ink-2 shadow-[0_8px_30px_-12px_rgba(0,0,0,.25)]">{info}</div>
      )}
      <button
        className="inline-flex h-9 w-9 cursor-pointer items-center justify-center rounded-full text-ink-3 hover:bg-soft hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
        onClick={async () => {
          if (!supported) return say('This browser cannot receive alerts. On iPhone: Share → Add to Home Screen, then open the app.')
          if (!on) {
            const text = await enableAlerts()
            setOn(text.startsWith('Alerts are on'))
            return say(text)
          }
          say(await sendTestAlert(''))
        }}
        title={on ? 'Send a test alert to this device' : 'Get launch alerts on this device'}
        aria-label={on ? 'Test alert' : 'Enable alerts'}
      >
        {on ? <BellRing size={17} /> : <Bell size={17} />}
      </button>
    </div>
  )
}
